<section class="card"><div class="card-body"><form data-directory-searchable method="get" action="<?= e(base_url('index.php')) ?>"><input type="hidden" name="page" value="<?= e($route) ?>"><div class="ep-search"><div><label for="executive-people-search" class="visually-hidden">Search <?= e(strtolower($titleLabel)) ?></label><input id="executive-people-search" class="form-control" type="search" name="q" value="<?= e($q) ?>" maxlength="100" placeholder="Search name, voter ID, Party ID or Sys No."></div><button class="btn btn-primary">Search</button><a class="btn btn-light" href="<?= e(url($route)) ?>">Reset</a></div>
