<div class="ep-chips" aria-label="Applied filters"><?php foreach($chipLabels as $key=>$label): if(!isset($filters[$key])){continue;}$remaining=$filters;unset($remaining[$key]);$value=$choices[$key][$filters[$key]]??$chipValues[$key][$filters[$key]]??$filters[$key]; ?><a href="<?= e(url($route,$remaining)) ?>" aria-label="Remove <?= e($label) ?> filter"><?= e($label) ?>: <?= e($value) ?> <i class="bi bi-x" aria-hidden="true"></i></a><?php endforeach; ?></div><p class="small text-secondary mb-0">Locations and totals follow your permitted records. Branch follows the voter’s polling station. Contact details are kept off this list.</p></div>
<div class="table-responsive"><table class="table align-middle ep-table"><thead><tr><th>Photo</th><th>Last name</th><th>First name</th><th>Gender</th><?php if($members): ?><th>Region</th><?php else: ?><th>Voter ID</th><?php endif; ?><th>Constituency</th><th>Electoral area</th><th>Polling station</th><th>Status</th><th><span class="visually-hidden">Open record</span></th></tr></thead><tbody>
<?php foreach($rows as $row): $profile=$row['membership_id']?url('member',['id'=>$row['membership_id']]):url('voter',['id'=>$row['id']]); ?><tr><td><?php if($row['has_photo']): ?><img class="ep-photo" src="<?= e(url('voter_photo',['id'=>$row['id']])) ?>" alt="Photo of <?= e($row['full_name']) ?>" loading="lazy"><?php else: ?><span class="ep-photo ep-placeholder" aria-label="No photo"><?= e(mb_strtoupper(mb_substr($row['full_name'],0,1))) ?></span><?php endif; ?></td><td><?= e($row['last_name']?:'Not recorded') ?></td><td><a class="fw-semibold" href="<?= e($profile) ?>"><?= e($row['first_name']?:$row['full_name']) ?></a><?php if(!$row['first_name']): ?><small class="ep-detail">Saved full name</small><?php endif; ?></td><td><?= e(label($row['gender'])) ?></td><td><?= e($members?($row['region']?:'Not assigned'):$row['voter_id']) ?><?php $officeLevel='region';require \App\View::path('security/executive/people/roles'); ?></td><td><?= e($row['constituency']?:'Not assigned') ?><?php if($row['membership_id']): ?><small class="ep-detail"><?php if(trim((string)$row['official_membership_id'])!==''): ?>Party ID: <?= e($row['official_membership_id']) ?><?php else: ?><span class="badge bg-warning text-dark">Sys No.: <?= e($row['member_number']) ?></span><?php endif; ?></small><?php endif; ?><?php $officeLevel='constituency';require \App\View::path('security/executive/people/roles'); ?></td><td><?= e($row['branch']?:'Branch not assigned') ?><?php $officeLevel='branch';require \App\View::path('security/executive/people/roles'); ?></td><td><?= e($row['station']?:'Not assigned') ?><small class="ep-detail"><?= e($row['station_code']??'') ?></small><?php $officeLevel='polling_station';require \App\View::path('security/executive/people/roles'); ?></td><td><?php if($row['is_deceased']): ?><span class="badge bg-secondary">Deceased</span><?php endif; ?><?php if($row['membership_id']): ?><?= badge($row['membership_status']) ?><?php $officeLevel='national';require \App\View::path('security/executive/people/roles'); ?><?php else: ?><span class="ep-detail">Nonmember</span><?php endif; ?></td><td><a class="btn btn-sm btn-light text-nowrap" href="<?= e($profile) ?>"><?= $row['membership_id']?'View member':'View voter' ?> <i class="bi bi-arrow-up-right" aria-hidden="true"></i></a></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="10"><div class="ep-empty"><i class="bi bi-search" aria-hidden="true"></i><h2 class="h6">No matching records</h2><p>Try another search or clear the filters. Access remains limited to your current offices.</p><a href="<?= e(url($route)) ?>">Clear filters</a></div></td></tr><?php endif; ?></tbody></table></div><div class="card-body"><?php require \App\View::path('shared/components/directory/pagination'); ?></div></section></div>
